// Sidebar — Adw.Sidebar
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles sidebar with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"
import type { SidebarMode } from "@/lib/enums"

export interface SidebarProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** gboolean, from Adw.Sidebar */
  dropPreload?: boolean

  /** Gtk.Filter, from Adw.Sidebar */
  filter?: ReactNode

  /** Gio.MenuModel, from Adw.Sidebar */
  menuModel?: ReactNode

  /** SidebarMode, from Adw.Sidebar */
  mode?: SidebarMode

  /** Gtk.Widget, from Adw.Sidebar */
  placeholder?: ReactNode

  /** guint, from Adw.Sidebar */
  selected?: number
}

export function Sidebar({ className, children }: SidebarProps) {
  return (
    <div className={cn(className)}>
      {children}
    </div>
  )
}
